// Same cursor logic as 20_Forms_EventsPoller, but filtered server-side to kinds:['result'] sources:['submitInitialRequest'].
// When the Apps Script Router Trigger community node is installed, replace "Every minute" + this node + "Router: n8n_events" with it.
const sd = $getWorkflowStaticData('global');
const params = { limit: 100, kinds: ['result'], sources: ['submitInitialRequest'] };
if (sd.afterEventId) params.afterEventId = sd.afterEventId; else params.afterTs = sd.afterTs || new Date(Date.now() - 24 * 3600 * 1000).toISOString();
return [{ json: { params } }];

// Advance the cursor and emit one normalised item per NEW Initial Request. The 'result' payload (InitialRequestHandler.rawLogResult) carries:
//   formId, internalEmployeeId, employeeName, employmentType, employeeType, siteName, positionTitle, hireDate, managerEmail, requesterEmail, systems[], plan306090, jrAssignment
const sd = $getWorkflowStaticData('global');
const r = $input.first().json;
if (r.pruned === true) { sd.afterEventId = null; sd.afterTs = new Date(Date.now() - 24 * 3600 * 1000).toISOString(); return []; }
const events = Array.isArray(r.events) ? r.events : [];
sd.seen = Array.isArray(sd.seen) ? sd.seen : [];
const seen = new Set(sd.seen);
const fresh = events.filter(e => e && e.eventId && !seen.has(e.eventId));
if (r.nextAfterEventId) { sd.afterEventId = r.nextAfterEventId; sd.afterTs = null; } else if (!sd.afterEventId) { sd.afterTs = new Date(Date.now() - 10 * 60 * 1000).toISOString(); }
for (const e of fresh) sd.seen.push(e.eventId);
if (sd.seen.length > 1000) sd.seen = sd.seen.slice(-1000);
return fresh.map(e => {
  const p = e.payload || {};
  const name = String(p.employeeName || '').trim();
  const sp = name.indexOf(' ');
  return { json: {
    eventId: e.eventId, workflowId: e.workflowId, internalEmployeeId: String(p.internalEmployeeId || ''),
    employeeName: name,
    // employeeName is "First Last" — split on the first space. For exact first/middle/last call Forms · Get Workflow / Get Context instead.
    firstName: sp > 0 ? name.slice(0, sp) : name, lastName: sp > 0 ? name.slice(sp + 1) : '',
    employmentType: p.employmentType || '', employeeType: p.employeeType || '', siteName: p.siteName || '', positionTitle: p.positionTitle || '',
    hireDate: p.hireDate || '', managerEmail: p.managerEmail || '', requesterEmail: p.requesterEmail || '', systems: p.systems || [], jrAssignment: p.jrAssignment || '',
    union: undefined   // portal does not send union status yet — George's mapper defaults to UNION
  } };
});

// George's SiteDocs title-code mapper (from mw4aXq7lq5W1EQBy "Map Job Title to SiteDocs Code", 2026-09-11 scheme) + the Forms siteDocsJobCode it maps to.
// Forms' id_setup.siteDocsJobCode enum is Hourly 1 | Hourly 2 | Salary 1 | Salary 2 | Supervisor | Manager (EmployeeIDSetup.html) — NOT the SiteDocs code.
const SITE_IS_UNION = $json.union !== false;
const normalize = (s) => (s || '').toLowerCase().replace(/[-_]/g, ' ').replace(/\s+/g, ' ').trim();
const title = normalize($json.positionTitle);
const HOURLY_TITLES = ['general cleaner', 'industrial cleaner', 'booth cleaner', 'janitorial', 'janitor', 'high pressure blaster', 'water blaster', 'general labor', 'dock worker', 'loader', 'facilities maintenance', 'skilled trades', 'equipment operator', 'piv', 'tug', 'sweeper', 'fork truck', 'driver'];
const SITE_SUP_TITLES = ['site manager', 'account manager', 'site supervisor', 'site team lead', 'general cleaner team lead', 'high pressure blaster team lead', 'project manager', 'hourly supervisor', 'team leader', 'tl'];
let siteDocsTitleCode = null, formsJobCode = 'Hourly 1';
if (SITE_SUP_TITLES.some(t => title.includes(t))) { siteDocsTitleCode = SITE_IS_UNION ? 'Site-Sup – Union' : 'Site-Sup'; formsJobCode = 'Supervisor'; }
else if (HOURLY_TITLES.some(t => title.includes(t))) { siteDocsTitleCode = SITE_IS_UNION ? 'HRLY-U' : 'HRLY'; formsJobCode = 'Hourly 1'; }
if (!siteDocsTitleCode) throw new Error('No SiteDocs title code for position "' + $json.positionTitle + '" (' + $json.workflowId + ') — add it to the mapper or handle manually');
return [{ json: Object.assign({}, $json, { siteDocsTitleCode, formsJobCode }) }];

// Pick the Litmos user whose name matches the manager (George: name match is more reliable than email across domains).
const ev = $('Normalise event').item.json;
const users = Array.isArray($json) ? $json : (Array.isArray($json.value) ? $json.value : ($json.Users || $json.users || (Array.isArray($json.body) ? $json.body : [])));
const wantEmail = String(ev.managerEmail || '').toLowerCase();
let hit = users.find(u => String(u.Email || u.email || '').toLowerCase() === wantEmail);
if (!hit && users.length === 1) hit = users[0];
return [{ json: { managerId: hit ? (hit.Id || hit.id) : null, managerMatch: hit ? 'email' : 'none', candidates: users.length } }];

// DSS (Litmos) username: initials + hire date YYYYMMDD + site abbreviation (George, confirmed 2026-09-14 against real records, e.g. AP20260514CAM).
// Password: GENERATED per run — never hard-coded. It is passed to Litmos and to Forms · Submit ID Setup (which stores it exactly as the UI does) and nowhere else.
const ev = $('Normalise event').item.json;
const first = (ev.firstName || '')[0] || '', last = (ev.lastName || '')[0] || '';
// hireDate arrives as yyyy-MM-dd — use the string directly (new Date('yyyy-MM-dd') is UTC midnight and shifts a day in local time, a latent bug in the original draft)
const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(ev.hireDate || ''));
const yyyymmdd = m ? m[1] + m[2] + m[3] : '00000000';
const siteAbbrev = (ev.siteName || '').replace(/[^a-zA-Z]/g, '').slice(0, 4).toUpperCase();   // TODO George: real site → abbreviation lookup
const dssUsername = (first + last + yyyymmdd + siteAbbrev).toUpperCase();
function randomPassword(len) {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!#$%&*+-=?@';
  let bytes;
  try { bytes = require('crypto').randomBytes(len); } catch (e) { bytes = Array.from({ length: len }, () => Math.floor(Math.random() * 256)); }   // crypto needs NODE_FUNCTION_ALLOW_BUILTIN=crypto
  let out = ''; for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
  return 'Tg' + out;   // guaranteed upper+lower prefix
}
const sd = $('SiteDocs: Create Worker').item.json;
const siteDocsWorkerId = String(sd.id || sd.Id || '');
if (!siteDocsWorkerId) throw new Error('SiteDocs: Create Worker returned no id for ' + ev.workflowId);
return [{ json: { workflowId: ev.workflowId, firstName: ev.firstName, lastName: ev.lastName, internalEmployeeId: ev.internalEmployeeId, siteDocsWorkerId, formsJobCode: $('Map title codes').item.json.formsJobCode, dssUsername, dssPassword: randomPassword(14), managerId: $('Resolve Manager ID').item.json.managerId || null } }];

// One error email per failed node. $json.error is set by "On Error → Continue (using error output)"; the node name tells you where it broke.
const j = $input.first().json;
const ev = (() => { try { return $('Normalise event').item.json; } catch (e) { return {}; } })();
const where = j.__failedNode || 'see execution';
const msg = String((j.error && j.error.message) || j.error || JSON.stringify(j).slice(0, 500));
return [{ json: {
  subject: '[EFX onboarding ref] FAILED — ' + (ev.employeeName || ev.workflowId || 'unknown') + ' @ ' + where,
  html: '<p><strong>Onboarding automation failed</strong></p><ul><li>Workflow: ' + (ev.workflowId || 'n/a') + '</li><li>Employee: ' + (ev.employeeName || 'n/a') + ' (#' + (ev.internalEmployeeId || 'n/a') + ')</li><li>Site: ' + (ev.siteName || 'n/a') + '</li><li>Failed at: ' + where + '</li></ul><pre>' + msg.replace(/</g, '&lt;') + '</pre><p>n8n execution ' + $execution.id + ' · ' + $workflow.name + '</p><p>Nothing was written to Forms unless the failure is at "Forms · Submit ID Setup" (check the ID Setup Results sheet). SiteDocs/Litmos objects created before the failure may need manual cleanup.</p>'
} }];
